/**
 * Rules for event additional forms, shared by the service, controller and export.
 * Frontend mirrors `checkFieldAnswer` in `frontend/src/components/eventForms/eventFormUtils.ts` - keep them in sync.
 */

export enum FormFieldType {
  shortText = "shortText",
  longText = "longText",
  number = "number",
  singleSelect = "singleSelect",
  multiSelect = "multiSelect",
  checkbox = "checkbox",
}

export enum EventFormStatus {
  complete = "complete",
  incomplete = "incomplete",
  missing = "missing",
}

export interface FormField {
  /** Stable UUID generated by the builder, answers are keyed by it */
  id: string;
  type: FormFieldType;
  label: string;
  description?: string;
  required: boolean;
  /** Only for `singleSelect` and `multiSelect` */
  options?: string[];
}

export type FormAnswers = Record<string, unknown>;

export type FieldCheck = "ok" | "empty" | "invalid";

export const FORM_LIMITS = {
  maxFields: 50,
  maxNameLength: 200,
  maxLabelLength: 200,
  maxDescriptionLength: 1000,
  maxOptions: 50,
  maxOptionLength: 200,
  maxTextAnswerLength: 5000,
} as const;

export const isSelectType = (type: FormFieldType) =>
  type === FormFieldType.singleSelect || type === FormFieldType.multiSelect;

const isEmptyValue = (value: unknown) =>
  value === undefined ||
  value === null ||
  (typeof value === "string" && value.trim() === "") ||
  (Array.isArray(value) && value.length === 0);

export const checkFieldAnswer = (field: FormField, value: unknown): FieldCheck => {
  if (field.type === FormFieldType.checkbox) {
    if (value === undefined || value === null) return "empty";
    if (typeof value !== "boolean") return "invalid";
    // Required checkbox works as a consent - only `true` counts as filled
    return field.required && !value ? "empty" : "ok";
  }

  if (isEmptyValue(value)) return "empty";

  const options = field.options ?? [];
  switch (field.type) {
    case FormFieldType.shortText:
    case FormFieldType.longText:
      return typeof value === "string" && value.length <= FORM_LIMITS.maxTextAnswerLength ? "ok" : "invalid";
    case FormFieldType.number:
      return typeof value === "number" && Number.isFinite(value) ? "ok" : "invalid";
    case FormFieldType.singleSelect:
      return typeof value === "string" && options.includes(value) ? "ok" : "invalid";
    case FormFieldType.multiSelect:
      return Array.isArray(value) &&
        value.every((item) => typeof item === "string" && options.includes(item)) &&
        new Set(value).size === value.length
        ? "ok"
        : "invalid";
    default:
      return "invalid";
  }
};

/**
 * Errors keyed by field ID - an entry for every invalid answer and every empty required answer
 */
export const validateAnswers = (fields: FormField[], answers: FormAnswers): Record<string, string> => {
  const errors: Record<string, string> = {};
  for (const field of fields) {
    const check = checkFieldAnswer(field, answers[field.id]);
    if (check === "invalid") errors[field.id] = `${field.label}: invalid value`;
    else if (check === "empty" && field.required) errors[field.id] = `${field.label}: this field is required`;
  }
  return errors;
};

/**
 * Computed on read so that adding a required field later marks older responses incomplete
 */
export const computeStatus = (fields: FormField[], answers: FormAnswers | null): EventFormStatus => {
  if (answers === null) return EventFormStatus.missing;
  const isComplete = fields.every((field) => !field.required || checkFieldAnswer(field, answers[field.id]) === "ok");
  return isComplete ? EventFormStatus.complete : EventFormStatus.incomplete;
};

export const splitAnswers = (fields: FormField[], answers: FormAnswers) => {
  const currentIds = new Set(fields.map((field) => field.id));
  const current: FormAnswers = {};
  const removed: FormAnswers = {};
  for (const [id, value] of Object.entries(answers)) {
    if (currentIds.has(id)) current[id] = value;
    else removed[id] = value;
  }
  return { current, removed };
};

/**
 * Answers to removed fields are kept so managers still see them, unknown submitted keys are dropped
 */
export const mergeAnswers = (fields: FormField[], previous: FormAnswers, submitted: FormAnswers): FormAnswers => {
  const { removed } = splitAnswers(fields, previous);
  const current: FormAnswers = {};
  for (const field of fields) {
    if (submitted[field.id] !== undefined) current[field.id] = submitted[field.id];
  }
  return { ...removed, ...current };
};

/**
 * Trims texts, drops empty descriptions and removes options from non-select fields
 */
export const normalizeFormFields = (fields: FormField[]): FormField[] =>
  fields.map((field) => {
    const description = field.description?.trim();
    return {
      id: field.id,
      type: field.type,
      label: field.label.trim(),
      ...(description ? { description } : {}),
      required: field.required,
      ...(isSelectType(field.type) ? { options: (field.options ?? []).map((option) => option.trim()) } : {}),
    };
  });

/**
 * Cross-field rules class-validator can't express. Expects normalized fields.
 */
export const validateFormFields = (fields: FormField[]): string[] => {
  const errors: string[] = [];
  const ids = new Set<string>();

  for (const field of fields) {
    if (ids.has(field.id)) errors.push(`Field ID ${field.id} is used more than once`);
    ids.add(field.id);

    if (field.label === "") errors.push("Every field needs a label");

    if (isSelectType(field.type)) {
      const options = field.options ?? [];
      if (options.length === 0) errors.push(`"${field.label}" needs at least one option`);
      if (options.some((option) => option === "")) errors.push(`"${field.label}" has an empty option`);
      if (new Set(options).size !== options.length) errors.push(`"${field.label}" has duplicate options`);
    }
  }

  return errors;
};
